    TreeNode left;
    TreeNode right;
    TreeNode(int val) { this.val = val; }
}

class TreeTraversal {
    // Inorder: left -> root -> right (sorted for BST)
    void inorder(TreeNode root) {
        if (root == null) return;
        inorder(root.left);
        System.out.print(root.val + " ");  // Process after left
        inorder(root.right);
    }

    // Preorder: root -> left -> right (copy/serialize)
    void preorder(TreeNode root) {
        if (root == null) return;
        System.out.print(root.val + " ");  // Process before children
        preorder(root.left);
        preorder(root.right);
    }

    // Postorder: left -> right -> root (delete/calculate)
    void postorder(TreeNode root) {
        if (root == null) return;
        postorder(root.left);
        postorder(root.right);
        System.out.print(root.val + " ");  // Process after children
    }
}

class BSTNode {
    int val;
    BSTNode left;
    BSTNode right;
    BSTNode(int val) { this.val = val; }
}

class BinarySearchTree {
    BSTNode root;

    // Search: O(log n) if balanced, O(n) if skewed
    boolean search(BSTNode node, int target) {
        if (node == null) return false;
        if (target == node.val) return true;
        // Use BST property to decide direction
        return target < node.val 
            ? search(node.left, target)
            : search(node.right, target);
    }

    // Insert: maintain BST property
    BSTNode insert(BSTNode node, int val) {
        if (node == null) return new BSTNode(val);
        if (val < node.val) {
            node.left = insert(node.left, val);  // Go left if smaller
        } else if (val > node.val) {
            node.right = insert(node.right, val);  // Go right if larger
        }
        return node;  // Duplicates ignored in this implementation
    }
}

