class TreeHeight {
    // Height = longest path from root to leaf (counting edges)
    int height(TreeNode root) {
        // Base case: null node has height -1
        if (root == null) return -1;

        // Recursively get heights of subtrees
        int leftHeight = height(root.left);
        int rightHeight = height(root.right);

        // Current height = 1 edge + max of subtree heights
        return 1 + Math.max(leftHeight, rightHeight);
    }

    // Alternative: count nodes in path instead of edges
    int depth(TreeNode root) {
        if (root == null) return 0;  // null returns 0
        return 1 + Math.max(depth(root.left), depth(root.right));
    }
}

